"""Test explicit reset configuration, EN4B and RDCR without array or NV writes."""
import argparse,json,struct
from pathlib import Path
from verify_mspi1_status_byte import SETUP
from verify_mspi1_write_enable import HELPERS,board as latch_board
from verify_mspi1_pio_reset import models
from native_replay import IMAGE
from run_renode_m55_probe import execute

def board(text,seed=0,complete=True):
 text=latch_board(text,64,True,complete)
 if seed is not None:text=text.replace('    profile: "idle-nor-reset"\n','    profile: "idle-nor-reset"\n    configurationByte: '+str(seed)+'\n')
 return text
ADDRESS_HELPERS='''def en4b():
    status_config();b.WriteDoubleWord(0x4006100c,0xb7);b.WriteDoubleWord(0x40061000,0xc1)
def rdcr():
    status_config();b.WriteDoubleWord(0x4006100c,0x15);b.WriteDoubleWord(0x40061000,0x10441)
'''
def phases(seed):
 value=seed|32
 return [(5,"check('EN4B-not-early',q.Busy and not q.FourByteAddressMode and q.Enter4ByteTransfers==0)\n"),(5,"check('EN4B-no-WREN-needed',not q.Busy and q.FourByteAddressMode and q.Enter4ByteTransfers==1 and q.CurrentConfigurationByte=="+str(value)+" and not q.WriteEnabled and q.RxEntries==0)\nrdcr();blocked('RDCR-premature-FIFO',lambda:b.ReadDoubleWord(0x40061014))\n"),(10,"check('RDCR-ready',q.ConfigurationReadTransfers==1 and q.RxEntries==1)\nblocked('RDCR-unread-not-overwritten',en4b)\ncheck('RDCR-bit5-and-TB',b.ReadDoubleWord(0x40061014)=="+str(value)+")\nblocked('RDCR-empty-FIFO',lambda:b.ReadDoubleWord(0x40061014))\nen4b()\n"),(10,"check('EN4B-repeat-idempotent',q.Enter4ByteTransfers==2 and q.FourByteAddressMode)\nwren()\n"),(10,"check('WREN-preserves-address-mode',q.WriteEnabled and q.FourByteAddressMode)\nstatus_start()\n"),(10,"check('RDSR-preserves-address-mode',b.ReadDoubleWord(0x40061014)==0x42 and q.FourByteAddressMode)\nreset_wire(0x66)\n"),(10,"check('RSTEN-preserves-address-mode',q.ResetArmed and q.FourByteAddressMode)\nreset_wire(0)\n"),(10,"check('NOP-preserves-address-mode',not q.ResetArmed and q.FourByteAddressMode)\nreset_wire(0x99)\n"),(10,"check('unarmed-reset-preserves-address-mode',q.IgnoredResets==1 and q.FourByteAddressMode)\nreset_wire(0x66)\n"),(10,"check('address-mode-rearmed',q.ResetArmed and q.FourByteAddressMode)\nreset_wire(0x99)\n"),(10,"check('armed-reset-restores-config-and-WEL',not q.FourByteAddressMode and q.CurrentConfigurationByte=="+str(seed)+" and not q.WriteEnabled and q.Recovering)\nblocked('RDCR-reset-recovery',rdcr)\n"),(100,"rdcr()\n"),(10,"check('RDCR-reset-defaults-and-TB',b.ReadDoubleWord(0x40061014)=="+str(seed)+")\nen4b();g.WriteDoubleWord(0x3110,0xa4214);g.WriteDoubleWord(0x3110,0xa4234)\n"),(10,"check('EN4B-clock-abort',q.Aborted==1 and not q.FourByteAddressMode and q.Enter4ByteTransfers==2)\nen4b();g.Reset()\n"),(20,"check('owner-reset-cancels-EN4B',not q.FourByteAddressMode and q.Enter4ByteTransfers==0 and q.CurrentConfigurationByte=="+str(seed)+")\nready();en4b()\n"),(10,"check('EN4B-after-owner-reset',q.FourByteAddressMode and q.Enter4ByteTransfers==1)\nstatus_config();b.WriteDoubleWord(0x4006100c,0x9f);b.WriteDoubleWord(0x40061000,0x30441)\n"),(10,"check('ID-preserves-address-mode',b.ReadDoubleWord(0x40061014)==0x3925c2 and q.FourByteAddressMode)\ng.Reset();ready()\nfor cmd in [1,3,0xe9]:\n    b.WriteDoubleWord(0x4006100c,cmd);blocked('unsupported-command-'+str(cmd),lambda:b.WriteDoubleWord(0x40061000,0xc1))\nstatus_config();b.WriteDoubleWord(0x4006100c,0xb7)\nblocked('EN4B-wrong-length',lambda:b.WriteDoubleWord(0x40061000,0x100c1))\nb.WriteDoubleWord(0x40061084,0x3010861)\nblocked('EN4B-wrong-config',lambda:b.WriteDoubleWord(0x40061000,0xc1))\ncheck('guards-preserve-mode',not q.FourByteAddressMode and q.CurrentConfigurationByte=="+str(seed)+")\n")]
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('simulator',type=Path);p.add_argument('output',type=Path);p.add_argument('--tb',action='store_true');p.add_argument('--unknown',action='store_true');p.add_argument('--stuck',action='store_true');a=p.parse_args();s=a.simulator;o=a.output;o.mkdir(mode=0o700);seed=None if a.unknown else 8 if a.tb else 0;(o/'board.repl').write_text(board((s/'mspi1-sampling-context-01/stock24/board.repl').read_text(),seed,not a.stuck));(o/'strict.cs').write_bytes(models(s));(o/'spin.bin').write_bytes(struct.pack('<II',0x20001000,0x10009)+bytes.fromhex('fee7'));setup=SETUP+HELPERS+ADDRESS_HELPERS;steps=[]
 if seed is None:setup+="blocked('unknown-config-no-EN4B',en4b)\nblocked('unknown-config-no-RDCR',rdcr)\n"
 else:
  setup+="check('explicit-reset-config',q.ConfigurationByte=="+str(seed)+" and q.CurrentConfigurationByte=="+str(seed)+" and not q.FourByteAddressMode)\nCtor=type(q)\nfor invalid in [-2,1,7,16,32,64,255,256]:\n    try:Ctor(m,'idle-nor-reset',p,g.Mspi1Clock,i,True,'mx25u25643g','ideal-sdr',64,True,invalid)\n    except Exception as e:check('invalid-config-seed-'+str(invalid),'Configuration seed must be unknown -1 or reset TB fixture 0/8' in str(e))\n    else:raise Exception('invalid config accepted')\nen4b()\ncheck('EN4B-start-not-mode-switch',q.Busy and not q.FourByteAddressMode)\n";steps=[(1000,"check('EN4B-stuck-no-switch',q.Busy and not q.FourByteAddressMode and q.Enter4ByteTransfers==0)\n")] if a.stuck else phases(seed)
 (o/'setup.py').write_text(setup);resc='include @/work/strict.cs\nmach create "address-mode"\nmachine LoadPlatformDescription @/work/board.repl\nsysbus LoadBinary @/work/spin.bin 0x10000\ncpu VectorTableOffset 0x10000\ninclude @/work/setup.py\n'
 for n,(us,code) in enumerate(steps):
  (o/f'phase-{n}.py').write_text(code);(o/f'advance-{n}.py').write_text('from Antmicro.Renode.Core import EmulationManager\nfrom Antmicro.Renode.Time import TimeInterval\nEmulationManager.Instance.CurrentEmulation.RunFor(TimeInterval.FromMicroseconds('+str(us)+'))\n');resc+=f'include @/work/advance-{n}.py\ninclude @/work/phase-{n}.py\n'
 (o/'result.py').write_text("Console.WriteLine('BLACKWALL_ADDRESS_UNIT '+json.dumps(dict(passed=True,count=len(checks),checks=checks,scope='limited reset config and EN4B/RDCR; no memory backing, NV writes or physical proof')))\n");(o/'probe.resc').write_text(resc+'include @/work/result.py\nquit\n');log=execute(['docker','run','--rm','--network','none','--memory','512m','--cpus','1','--pids-limit','128','--cap-drop','ALL','--security-opt','no-new-privileges','--mount',f'type=bind,source={o},target=/work,readonly',IMAGE,'--disable-gui','--console','-p','-e','quit','/work/probe.resc'],o,'renode');rows=[json.loads(x.split(' ',1)[1]) for x in log.splitlines() if x.startswith('BLACKWALL_ADDRESS_UNIT ')]
 if len(rows)!=1:raise ValueError('Missing address-mode result; inspect preserved log')
 (o/'report.json').write_text(json.dumps(rows[0],indent=2)+'\n');print(json.dumps(dict(passed=rows[0]['passed'],count=rows[0]['count'])))
if __name__=='__main__':main()
